// Cache validity bit flags
// cached data is invalid
// cached atime is invalid
// cached access cred invalid
// cached acls are invalid
// force revalidation ignoring a delegation
// cached change is invalid
// cached ctime is invalid
// cached mtime is invalid
// cached size is invalid
// other attrs are invalid
// Deferred cache invalidation
// cached blocks are invalid
// xattrs are invalid
// cached nlinks is invalid
// cached mode is invalid
// cached btime is invalid
// cached uncacheable_file_data is invalid
// inode metadata is invalid
// Bit offsets in flags field
// possible stale inode
// inode is being invalidated
// layoutcommit required
// layoutcommit inflight
// I/O setting is O_DIRECT
// Request a directory delegation
fn NFS_I(inode: *const inode) -> *mut nfs_inode {
container_of!(inode, nfs_inode)
}

fn NFS_SB(s: *const super_block) -> *mut nfs_server {
(unsafe { (*s).s_fs_info }) as *mut nfs_server
}

fn NFS_FH(inode: *const inode) -> *mut nfs_fh {
unsafe { core::ptr::addr_of_mut!((*NFS_I(inode)).fh) }
}

fn NFS_SERVER(inode: *const inode) -> *mut nfs_server {
NFS_SB((unsafe { (*inode).i_sb }) as *const super_block)
}

fn NFS_PROTO(inode: *const inode) -> *const nfs_rpc_ops {
unsafe { (*(*NFS_SERVER(inode)).nfs_client).rpc_ops }
}

fn NFS_MINATTRTIMEO(inode: *const inode) -> u32 {
let nfss: *mut nfs_server = NFS_SERVER(inode);
if S_ISDIR!(unsafe { (*inode).i_mode }) { unsafe { (*nfss).acdirmin } } else { unsafe { (*nfss).acregmin } }
}

fn NFS_MAXATTRTIMEO(inode: *const inode) -> u32 {
let nfss: *mut nfs_server = NFS_SERVER(inode);
if S_ISDIR!(unsafe { (*inode).i_mode }) { unsafe { (*nfss).acdirmax } } else { unsafe { (*nfss).acregmax } }
}

fn NFS_STALE(inode: *const inode) -> i32 {
test_bit__2!(1i32, unsafe { core::ptr::addr_of_mut!((*NFS_I(inode)).flags) })
}

fn nfs_server_capable(inode: *const inode, cap: i32) -> i32 {
((unsafe { (*NFS_SERVER(inode)).caps }) & (cap as u32)) as i32
}

